from token_stream import extract_words

class LineWrapper:
    def wrap(self, text: str, width: int) -> list[str]:
        if not text.strip() or width <= 0:
            return []
        words = extract_words(text)
        split_words = []
        for w in words:
            if len(w) > width:
                for i in range(0, len(w), width):
                    split_words.append(w[i:i + width])
            else:
                split_words.append(w)

        lines = []
        cur_line = []
        cur_len = 0
        for w in split_words:
            added = len(w) if not cur_line else len(w) + 1
            if cur_line and cur_len + added > width:
                lines.append(" ".join(cur_line))
                cur_line = [w]
                cur_len = len(w)
            else:
                cur_line.append(w)
                cur_len += added
        if cur_line:
            lines.append(" ".join(cur_line))
        return lines
